components.css:
.ds-btn-primary {
  display: inline-flex; align-items: center; justify-content: center;
  height: 32px; padding: 8px 15px; border: 1px solid #C9451F; border-radius: 4px;
  background: #C9451F; color: #FFFFFF; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 14px; font-weight: 600; line-height: 1; cursor: pointer;
  transition: background-color .15s ease, border-color .15s ease;
}
.ds-btn-primary:hover { background: #B93C18; border-color: #B93C18; }
.ds-btn-primary:active { background: #A32F10; border-color: #A32F10; }
.ds-btn-primary:focus-visible { outline: 2px solid #0E7C7B; outline-offset: 2px; }

.ds-input {
  width: 100%; max-width: 320px; height: 32px; padding: 1px 11px;
  border: 0; border-radius: 4px; background: #FFFFFF; color: #0B1B2B;
  box-shadow: 0 0 0 1px #8C8777 inset; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 14px; line-height: 32px; outline: none;
  transition: box-shadow .15s ease;
}
.ds-input::placeholder { color: #6B7681; }
.ds-input:hover { box-shadow: 0 0 0 1px #6B7681 inset; }
.ds-input:focus { box-shadow: 0 0 0 1px #0B1B2B inset; }
.ds-input:focus-visible { outline: 2px solid #0E7C7B; outline-offset: 2px; }

.ds-rail-nav {
  display: flex; align-items: center; gap: 4px; padding: 0 12px;
  background: #14293D; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
}
.ds-nav-link {
  display: inline-flex; align-items: center; padding: 20px 12px;
  border-bottom: 2px solid transparent; color: rgba(255,255,255,.65);
  font-size: 14px; font-weight: 600; line-height: 20px; text-decoration: none;
  transition: color .15s ease, border-color .15s ease;
}
.ds-nav-link:hover { color: #FFFFFF; }
.ds-nav-link.is-active { color: #FFFFFF; border-bottom-color: #C9451F; }
.ds-nav-link:focus-visible { outline: 2px solid #0E7C7B; outline-offset: -2px; }

.ds-chips { display: flex; align-items: center; gap: 8px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; }
.ds-line-chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 3px 7px;
  border-radius: 3px; background: var(--chip, #0B1B2B); color: #FFFFFF;
  font-size: 11px; font-weight: 700; line-height: 1.2; letter-spacing: .06em;
  text-transform: uppercase; font-variant-numeric: tabular-nums;
}
.ds-line-chip--outline {
  background: transparent; color: var(--chip, #0B1B2B);
  box-shadow: inset 0 0 0 1px currentColor;
}

.ds-resource-card {
  display: block; overflow: hidden; border: 1px solid #DCD9CF; border-radius: 4px;
  background: #FFFFFF; color: #0B1B2B; text-decoration: none; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.ds-resource-card:hover {
  transform: translateY(-2px); border-color: rgba(11,27,43,.25);
  box-shadow: 0 10px 30px -18px rgba(11,27,43,.45);
}
.ds-resource-card:focus-visible { outline: 2px solid #0E7C7B; outline-offset: 2px; }
.ds-resource-card__media {
  position: relative; display: flex; align-items: center; justify-content: center;
  aspect-ratio: 16 / 9; background: #F5F4EF; overflow: hidden;
}
.ds-resource-card__track { position: absolute; left: 0; right: 0; top: 50%; height: 2px; background: #DCD9CF; }
.ds-resource-card__station {
  position: relative; z-index: 1; width: 10px; height: 10px; border: 2px solid #0E7C7B;
  border-radius: 999px; background: #FFFFFF;
}
.ds-resource-card__initial { margin-left: 12px; font-size: 24px; font-weight: 700; color: rgba(11,27,43,.2); }
.ds-resource-card__body { padding: 16px; }
@media (min-width: 640px) { .ds-resource-card__body { padding: 20px; } }
.ds-resource-card__meta { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.ds-resource-card__category { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; color: #6B7681; }
.ds-line-chip {
  display: inline-flex; align-items: center; padding: 3px 7px; border-radius: 3px;
  background: var(--chip, #0B1B2B); color: #FFFFFF; font-size: 11px; font-weight: 700;
  line-height: 1.2; letter-spacing: .06em; text-transform: uppercase;
  font-variant-numeric: tabular-nums;
}
.ds-resource-card__title { margin: 12px 0 0; font-size: 16px; font-weight: 600; line-height: 1.35; }
.ds-resource-card__desc {
  margin: 6px 0 0; font-size: 14px; line-height: 1.625; color: #4A5763;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.ds-resource-card__reason { display: flex; align-items: flex-start; gap: 8px; margin: 12px 0 0; font-size: 12px; line-height: 1.625; color: #0E7C7B; }
.ds-resource-card__reason-dot { flex: none; width: 6px; height: 6px; margin-top: 6px; border-radius: 999px; background: currentColor; }
.ds-resource-card__footer {
  display: flex; align-items: center; justify-content: space-between; margin-top: 16px;
  padding-top: 12px; border-top: 1px solid #DCD9CF; font-size: 12px; color: #6B7681;
  font-variant-numeric: tabular-nums;
}

.ds-route-strip {
  display: flex; align-items: flex-start; gap: 0; margin: 0; padding: 0;
  list-style: none; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
}
.ds-route-strip__stop {
  position: relative; display: flex; flex: 1; min-width: 0; flex-direction: column;
  align-items: flex-start; gap: 8px; padding-top: 14px; color: #0B1B2B;
}
.ds-route-strip__stop::before {
  content: ""; position: absolute; top: 5px; left: 0; right: 0; height: 2px;
  background: var(--track, #DCD9CF);
}
.ds-route-strip__stop:first-child::before { left: 6px; }
.ds-route-strip__stop:last-child::before { right: calc(100% - 6px); }
.ds-route-strip__dot {
  position: absolute; top: 0; left: 0; box-sizing: border-box; width: 12px; height: 12px;
  border: 3px solid var(--node, #0B1B2B); border-radius: 999px; background: #FFFFFF;
}
.ds-route-strip__stop[data-state="done"] .ds-route-strip__dot { background: var(--node, #15803D); }
.ds-route-strip__stop[data-state="current"] .ds-route-strip__dot {
  background: var(--node, #C9451F); border-color: var(--node, #C9451F);
  box-shadow: 0 0 0 4px rgba(201,69,31,.18);
}
.ds-route-strip__stop[data-state="locked"] { color: #6B7681; }
.ds-route-strip__label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; line-height: 1.3; }

.ds-sticky-bar {
  position: sticky; bottom: 16px; display: flex; flex-wrap: wrap; align-items: center;
  justify-content: space-between; gap: 12px; padding: 12px 20px; border: 1px solid #DCD9CF;
  border-radius: 4px; background: #FFFFFF; box-shadow: 0 10px 30px -18px rgba(11,27,43,.45);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
}
.ds-sticky-bar__count { font-size: 12px; color: #6B7681; font-variant-numeric: tabular-nums; }
.ds-btn-primary {
  display: inline-flex; align-items: center; justify-content: center;
  height: 32px; padding: 8px 15px; border: 1px solid #C9451F; border-radius: 4px;
  background: #C9451F; color: #FFFFFF; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 14px; font-weight: 600; line-height: 1; cursor: pointer;
  transition: background-color .15s ease, border-color .15s ease;
}
.ds-btn-primary:hover { background: #B93C18; border-color: #B93C18; }
.ds-btn-primary:active { background: #A32F10; border-color: #A32F10; }
.ds-btn-primary:focus-visible { outline: 2px solid #0E7C7B; outline-offset: 2px; }
